# -*- coding: utf-8 -*-
S = "полный обзор задач 10 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G10_TB_§9_9_21_4", r"$\sqrt[3]{a^{3}}=a$, поэтому $a=-a \Leftrightarrow a=0$; в ключе стояло $a\le0$",
  k=r"$a = 0$",
  dnew={0: (r"$a \ge 0$", "Ученик решил $a=-a$, получил $a=0$, но записал ответ как область $a\\ge0$ вместо единственного значения."),
        1: (r"$a \le 0$", "Ученик перенёс ответ для равенства $\\sqrt[4]{a^{4}}=-a$ (там $|a|=-a$ и $a\\le0$); для корня нечётной степени $\\sqrt[3]{a^{3}}=a$, и равенство $a=-a$ верно только при $a=0$."),
        2: (r"$a < 0$", "Ученик решил, что знак «минус» справа требует отрицательного $a$, но при $a<0$ левая часть $a<0$, а правая $-a>0$, и равенство не выполняется.")})
E("G10_TB_§9_9_26_5", r"$\sqrt[12]{m^{36}n^{60}}=|m|^{3}|n|^{5}=(-m)^{3}(-n)^{5}=m^{3}n^{5}$ при $m\le0$, $n\le0$ (корень чётной степени неотрицателен, а $m^{3}n^{5}\ge0$); в ключе был лишний минус",
  k=r"$m^{3} n^{5}$",
  dnew={0: (r"$-m^{3} n^{5}$", "Ученик заменил $|m|^{3}$ на $-m^{3}$, но не учёл, что и $n\\le0$, поэтому $|n|^{5}=-n^{5}$; два минуса дают плюс, а результат корня чётной степени неотрицателен."),
        1: (r"$-m^{3} n^{6}$", "Ученик неверно разделил показатель: $60:12=6$ вместо $5$, и поставил лишний минус."),
        2: (r"$m^{3} n^{6}$", "Ученик верно определил знак, но неверно разделил показатель: $60:12=6$ вместо $5$.")})
E("G10_TB_•_2", r"$\sqrt{x}$ и $\sqrt{y}$ определены только при $x,y\ge0$; функция $t^{4}+\sqrt{t}$ возрастает на $[0;+\infty)$, поэтому $x=y$, $x^{2}=1$, $x=1$: единственное решение $(1;1)$ ($(-1;-1)$ не входит в ОДЗ)",
  k=r"$(1;1)$",
  dnew={0: (r"$(1;1); (-1;1); (1;-1); (-1;-1)$", "Ученик решил второе уравнение как $x^{2}=1$, $y^{2}=1$ и выписал все четыре комбинации знаков, не учтя ОДЗ: $\\sqrt{x}$ и $\\sqrt{y}$ требуют $x\\ge0$, $y\\ge0$."),
        2: (r"$(1;1); (-1;-1)$", "Ученик нашёл симметричное решение $(-1;-1)$ по чётности степеней, не проверив ОДЗ: $\\sqrt{-1}$ не определён.")})
E("G10_TB_•_5", r"$x=0$ — корень при $a^{2}=1$; при $a=-1$ корнями также являются $x=\pm1$ ($-1+1=0=\sqrt{0}$), а при $a=1$ левая часть $\ge1\ge$ правой, равенство только при $x=0$: $a=1$",
  k=r"$a = 1$",
  dnew={0: (r"$a = -1$", "Ученик нашёл $a^{2}=1$ (из корня $x=0$), но не проверил $a=-1$: там есть ещё корни $x=1$ и $x=-1$, поэтому корень не единственный."),
        1: (r"$a = 0$", "Ученик подставил $a=0$: получилось $1=0$, то есть корней нет; условие требует единственный корень."),
        2: (r"$a = \pm 1$", "Ученик из $a^{2}=1$ взял оба значения, не проверив $a=-1$: при нём есть корни $x=0$ и $x=\\pm1$.")})
E("G10_TB_•_5_25_4", r"$(x+5)^{2}\ge0$ и обращается в $0$ при $x=-5$: решение $x<a$, $x\ne-5$; при $a=-5$ это $(x+5)^{3}<0$, $x<-5$",
  k=r"Если $a \le -5$, то $x \in (-\infty; a)$; если $a > -5$, то $x \in (-\infty; -5) \cup (-5; a)$",
  dnew={0: (r"Если $a = -5$, то $x \in (-\infty; -5) \cup (-5; +\infty)$; если $a < -5$, то $x \in (a; -5)$; если $a > -5$, то $x \in (-5; a)$", "Ученик искал решения только между корнями $a$ и $-5$, не заметив, что $(x+5)^{2}\\ge0$ не меняет знак: нужно $x-a<0$, то есть $x<a$."),
        1: (r"Если $a = -5$, то решений нет; если $a < -5$, то $x \in (a; -5)$; если $a > -5$, то $x \in (-5; a)$", "Ученик решил, что при $a=-5$ неравенство $(x+5)^{3}<0$ не имеет решений; на самом деле оно верно при $x<-5$. Остальные случаи взял между корнями."),
        2: (r"Если $a \le -5$, то $x \in (-\infty; a)$; если $a > -5$, то $x \in (-\infty; a)$", "Ученик забыл исключить $x=-5$ при $a>-5$: в этой точке левая часть равна $0$, а неравенство строгое.")})
E("G10_TB_•_5_25_5", r"$x=-5$ всегда решение; при $x\ne-5$ нужно $x\le a$; при $a=-5$ имеем $(x+5)^{3}\le0$, $x\le-5$; при $a<-5$ добавляется изолированная точка $x=-5$",
  k=r"Если $a \ge -5$, то $x \in (-\infty; a]$; если $a < -5$, то $x \in (-\infty; a] \cup \{-5\}$",
  dnew={0: (r"Если $a < -5$, то $x \in [a; -5]$; если $a > -5$, то $x \in [-5; a]$", "Ученик искал решения между корнями $a$ и $-5$, не заметив, что $(x+5)^{2}\\ge0$ не меняет знак: нужно $x-a\\le0$, то есть $x\\le a$ (плюс точка $x=-5$)."),
        1: (r"Если $a = -5$, то $x \in (-\infty; -5] \cup [-5; +\infty)$; если $a < -5$, то $x \in [a; -5]$; если $a > -5$, то $x \in [-5; a]$", "Ученик при $a=-5$ записал решение неравенства $(x+5)^{3}\\le0$ как всю ось, хотя верно $x\\le-5$; остальные случаи взял между корнями."),
        2: (r"Если $a < -5$, то $x \in (-\infty; a]$; если $a > -5$, то $x \in [a; +\infty)$", "Ученик потерял изолированное решение $x=-5$ при $a<-5$ и при $a>-5$ перепутал направление неравенства: получил $x\\ge a$ вместо $x\\le a$.")})
E("G10_TB_•_5_25_7", r"при $x\ne-1$ дробь равна $x-a$: $x\ge a$, $x\ne-1$; при $a=-1$ получаем $x>-1$; при $a>-1$ точка $-1$ не входит в $[a;+\infty)$",
  k=r"Если $a < -1$, то $x \in [a; -1) \cup (-1; +\infty)$; если $a = -1$, то $x \in (-1; +\infty)$; если $a > -1$, то $x \in [a; +\infty)$",
  dnew={0: (r"Если $a < -1$, то $x \in [a; -1) \cup (-1; +\infty)$; если $a = -1$, то $x \in (-\infty; -1) \cup (-1; +\infty)$; если $a > -1$, то $x \in (-\infty; -1) \cup [a; +\infty)$", "Ученик включил лишние промежутки левее $-1$: после сокращения на $x+1$ остаётся $x-a\\ge0$ при $x\\ne-1$, а при $a=-1$ это $x>-1$."),
        1: (r"Если $a < -1$, то $x \in [a; +\infty)$; если $a = -1$, то $x \in \mathbb{R}$; если $a > -1$, то $x \in (-\infty; a]$", "Ученик сократил $(x+1)$, забыв исключить $x=-1$, и при $a>-1$ перепутал направление: получил $x\\le a$ вместо $x\\ge a$."),
        2: (r"Если $a < -1$, то $x \in (-\infty; a] \cup (-1; +\infty)$; если $a = -1$, то $x \in (-\infty; -1) \cup (-1; +\infty)$; если $a > -1$, то $x \in (-\infty; -1) \cup [a; +\infty)$", "Ученик верно исключил $x=-1$, но перепутал знак неравенства при $a<-1$ и при $a=-1$ забыл, что остаётся $x+1\\ge0$, то есть $x>-1$.")})
E("G10_TB_§9_9_4_7", r"$\sqrt[6]{729a^{54}b^{18}}=3|a|^{9}|b|^{3}$: корень чётной степени неотрицателен, а знаки $a,b$ в условии не заданы",
  k=r"$3|a|^{9}|b|^{3}$",
  dnew={2: (r"$3a^{9}b^{3}$", "Ученик не учёл, что корень чётной степени неотрицателен: при $a<0$ или $b<0$ выражение $3a^{9}b^{3}$ может быть отрицательным.")})
